export function splitRunEvidence(outcome) {
  const named = [];
  const infrastructure = [];
  for (const f of outcome.failures ?? []) {
    const name = typeof f?.name === 'string' ? f.name.trim() : '';
    if (name !== '' && !name.startsWith('(')) {
      if (!named.includes(name)) named.push(name);
    } else {
      infrastructure.push(name === '' ? '(unnamed)' : name);
    }
  }
  let evidence;
  if (outcome.pass) evidence = 'passed';
  else if (!outcome.loaded || outcome.timedOut || named.length === 0) evidence = 'no-evidence';
  else evidence = 'proves-test';
  return { evidence, named, infrastructure };
}

